"""Reconstruct LifeOS Today v17 from the preserved v16 HTML.

Usage:
    python apply_v16_to_v17.py path/to/v16.html [path/to/v17.html]
"""
from __future__ import annotations

import base64
import gzip
import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

PATCH_GZ_B64 = """"""
EXPECTED_SHA256 = "9c72ec8c1c814cb09d3e1b995eafd93961c841fe02c1d045bdd347d4a0effadf"


def main() -> int:
    if len(sys.argv) < 2:
        raise SystemExit("Pass the v16 HTML path")
    source = Path(sys.argv[1]).resolve()
    target = Path(sys.argv[2]).resolve() if len(sys.argv) > 2 else source.with_name("lifeos-home-oggi-v17.html")
    patch_bytes = gzip.decompress(base64.b64decode(PATCH_GZ_B64))
    with tempfile.NamedTemporaryFile(suffix=".patch", delete=False) as tmp:
        tmp.write(patch_bytes)
        patch_path = Path(tmp.name)
    try:
        subprocess.run(
            ["patch", str(source), "-i", str(patch_path), "-o", str(target)],
            check=True,
            text=True,
        )
    finally:
        patch_path.unlink(missing_ok=True)
    digest = hashlib.sha256(target.read_bytes()).hexdigest()
    if digest != EXPECTED_SHA256:
        target.unlink(missing_ok=True)
        raise SystemExit(f"SHA-256 mismatch: {digest}")
    print(f"Restored {target} (SHA-256 {digest})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
